page_content:
messages.append({
                        "role": "user",
                        "content": [
                            {
                                "type": "tool_result",
                                "tool_use_id": tool_use_id,
                                "content": formatted_results
                            }
                        ]
                    })
                else:
                    # Unknown tool
                    messages.append({
                        "role": "assistant",
                        "content": response.content
                    })

messages.append({
                        "role": "user",
                        "content": [
                            {
                                "type": "tool_result",
                                "tool_use_id": tool_use_id,
                                "content": f"Error: Unknown tool '{tool_name}'"
                            }
                        ]
                    })

        # If no tool was used, Claude has finished the response
        if not has_tool_use:
            # Extract and print the final response
            for content_block in response.content:
                if hasattr(content_block, 'text'):
                    print("\n[Claude's Response]")
                    print("=" * 60)
                    print(content_block.text)
            break

        # If tool was used but we've hit max iterations
        if iteration >= max_iterations:
            print("\nMax iterations reached. Tool use loop ended.")

